function ProjectCard({ project, index, isVisible }: { project: any, index: number, isVisible: boolean }) {
  const [imgIndex, setImgIndex] = useState(0)
  const [isHovered, setIsHovered] = useState(false)

  useEffect(() => {
    let interval: any
    if (isHovered && project.images.length > 1) {
      interval = setInterval(() => {
        setImgIndex((prev) => (prev + 1) % project.images.length)
      }, 1500)
    } else {
      setImgIndex(0)
    }
    return () => clearInterval(interval)
  }, [isHovered, project.images.length])

  return (
    <div
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      className={`group relative overflow-hidden rounded-2xl bg-card transition-all duration-700 ${
        isVisible ? "translate-y-0 opacity-100" : "translate-y-12 opacity-0"
      }`}
      style={{ transitionDelay: `${(index + 1) * 150}ms` }}
    >
      <div className="relative aspect-[4/5] overflow-hidden">
        {project.images.map((img: string, i: number) => (
          <Image
            key={img}
            src={img}
            alt={`${project.title} - Vista ${i + 1}`}
            fill
            className={`object-cover transition-all duration-1000 group-hover:scale-110 ${
              i === imgIndex ? "opacity-100 scale-100" : "opacity-0 scale-105"
            }`}
          />
        ))}
        
        {/* Gradient Overlay */}
        <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/20 to-transparent opacity-70 transition-opacity group-hover:opacity-90" />
        
        {/* Project Info */}
        <div className="absolute inset-0 flex flex-col justify-end p-6 text-white">
          <div className="flex items-center justify-between mb-2">
            <span className="w-fit rounded-full bg-primary/20 px-3 py-1 text-[10px] font-semibold uppercase tracking-wider backdrop-blur-md">
              {project.category}
            </span>
            {project.images.length > 1 && isHovered && (
              <span className="text-[10px] font-medium text-white/50 animate-pulse">
                Vista {imgIndex + 1}/{project.images.length}
              </span>
            )}
          </div>
          <h3 className="font-serif text-xl font-bold leading-tight sm:text-2xl">
            {project.title}
          </h3>
          <div className="mt-2 flex items-center gap-1 text-white/70">
            <MapPin className="h-3 w-3" />
            <span className="text-xs">{project.location}</span>
          </div>
          <p className="mt-3 max-h-0 overflow-hidden text-sm text-white/70 transition-all duration-500 group-hover:max-h-20">
            {project.description}
          </p>
        </div>
      </div>
    </div>
  )
}

export function ProyectosDestacados() {
  const sectionRef = useRef<HTMLElement>(null)
  const [isVisible, setIsVisible] = useState(false)
  const [currentPage, setCurrentPage] = useState(0)
  const itemsPerPage = 3
  const totalPages = Math.ceil(featuredProjects.length / itemsPerPage)

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
        }
      },
      { threshold: 0.1 }
    )
    if (sectionRef.current) {
      observer.observe(sectionRef.current)
    }
    return () => observer.disconnect()
  }, [])

  const currentProjects = featuredProjects.slice(
    currentPage * itemsPerPage,
    (currentPage + 1) * itemsPerPage
  )

  return (
    <section ref={sectionRef} className="relative overflow-hidden bg-background py-24 lg:py-32">
      {/* Background Pattern (Architectural Grid) */}
      <div 
        className="absolute inset-0 pointer-events-none opacity-[0.15]"
        style={{
          backgroundImage: `
            linear-gradient(to right, rgba(255,255,255,0.05) 1px, transparent 1px),
            linear-gradient(to bottom, rgba(255,255,255,0.05) 1px, transparent 1px)
          `,
          backgroundSize: '40px 40px',
          maskImage: 'radial-gradient(circle at center, black 40%, transparent 90%)',
          WebkitMaskImage: 'radial-gradient(circle at center, black 40%, transparent 90%)'
        }}
      />

      <div className="relative z-10 mx-auto max-w-7xl px-6 lg:px-8">
        <div className="flex flex-col items-end justify-between gap-6 md:flex-row md:items-center">
          <div className={`max-w-2xl transition-all duration-700 ${isVisible ? "translate-y-0 opacity-100" : "translate-y-8 opacity-0"}`}>
            <span className="text-xs font-semibold uppercase tracking-[0.2em] text-primary">
              Portafolio Seleccionado
            </span>
            <h2 className="mt-3 font-serif text-3xl font-bold text-foreground sm:text-4xl lg:text-5xl">
              Proyectos Destacados
            </h2>
          </div>
          <a
            href="/proyectos"
            className={`group flex items-center gap-2 text-sm font-semibold text-primary transition-all duration-700 delay-200 ${isVisible ? "translate-y-0 opacity-100" : "translate-y-8 opacity-0"}`}
          >
            Ver todos los proyectos
            <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
          </a>
        </div>

        <div className="mt-16 grid gap-8 sm:grid-cols-2 lg:grid-cols-3 min-h-[500px]">
          {currentProjects.map((project, index) => (
            <ProjectCard 
              key={`${project.title}-${currentPage}`} 
              project={project} 
              index={index} 
              isVisible={isVisible} 
            />
          ))}
        </div>

        {/* Pagination Dots */}
        {totalPages > 1 && (
          <div className="mt-12 flex items-center justify-center gap-3">
            {[...Array(totalPages)].map((_, i) => (
              <button
                key={i}
                onClick={() => setCurrentPage(i)}
                className={`h-2.5 rounded-full transition-all duration-500 ${
                  currentPage === i
                    ? "w-10 bg-primary"
                    : "w-2.5 bg-border hover:bg-primary/40"
                }`}
                aria-label={`Ir a la pagina ${i + 1}`}
              />
            ))}
          </div>
        )}
      </div>
    </section>
  )
}
